{
  "conditions": {
    "C1": {
      "passed": true,
      "evidence": ["E11989", "E11995", "CMD:c2e86cd9-2a96-43fe-b871-54e485e602ab"],
      "reason": "채택된 목표와 실제 명령 모두 T메일 취소이며, 음성 중단이나 두 업무 전체 취소로 바뀌지 않았다."
    },
    "C2": {
      "passed": true,
      "evidence": ["E11995", "E12002", "E12010"],
      "reason": "T메일/X메일을 대상으로 취소 명령이 접수됐다. 원래 실행의 ACCEPTED 사실도 기록됐으며 다른 메일이나 보고서를 취소 대상으로 선택하지 않았다."
    },
    "C3": {
      "passed": true,
      "evidence": ["E12002", "E12005"],
      "reason": "취소 명령은 T메일에만 연결됐고 T보고서는 RUNNING으로 유지됐다. 새 메일 Task/실행은 확인되지 않았다."
    },
    "C4": {
      "passed": true,
      "evidence": ["E11995", "E12002"],
      "reason": "취소 범위는 메일 업무다. 보고서는 유지됐고 T메일의 기존 수신자·자료 정보도 변경되지 않았으며 상태는 종료가 아닌 취소 접수/종료 미확인이다."
    },
    "C5": {
      "passed": true,
      "evidence": ["E11995", "E12002", "E12010", "E12014", "E12015", "CMD:c2e86cd9-2a96-43fe-b871-54e485e602ab"],
      "reason": "고유 CANCEL 명령은 1회 접수됐고 보고서 CANCEL은 없었다. 중복 취소 receipt는 무시됐으며, 지연 ACCEPTED 뒤에도 최종 상태는 CANCEL_ACCEPTED_TERMINATION_UNKNOWN으로 유지됐다."
    },
    "C6": {
      "passed": false,
      "evidence": ["P:1:849e3457-c231-4063-8804-1d7490e637e0", "E12038", "E12046"],
      "reason": "실제 음성 전달은 메일 취소 접수와 실행 종료 미확인을 정확히 알렸고 취소 완료를 주장하지 않았다. 그러나 보고서가 계속된다는 필수 사실은 실제 전달 문구에 없다."
    }
  },
